// Generated by the Salvo compiler: the actor scheduler — asynchronous
// effect handlers' runtime. The Kotlin mirror of the Rust backend's
// scheduler module; the semantics are LANGUAGE_SPEC.md's [actor-kind] …
// [actor-watch] and must stay identical on both
// backends: run-to-completion activations on pool threads, per-actor
// bounded queues (bound explicit at spawn; a full queue blocks the
// sender), reply tokens with reserved capacity (a reply never blocks and
// never counts against the bound), the gate (at most one outstanding per
// actor; while gated only the awaited reply is delivered), death = a
// faulted activation caught at the dispatch boundary (sends and replies
// to the dead are silent no-ops; watchers are notified with the reason),
// the quiescence hook ([actor-on-idle]: a registered token answered when
// nothing anywhere can run), and the deadlock report — nothing left that can
// run while a frame waits, and no hook to fire, is a named runtime error
// rather than a hang. The waiting frame need not be main: an activation
// parked in a nested wait holds its actor's `running` flag, so its own
// mailbox is stalled while it waits, and the report counts parked frames out
// of the running ones. Pool threads are daemon threads: the program ends when
// main returns.
//
// [main-pool] [waitfor-pump] `main` is the **single worker of its own pool**
// (pool 0), which is given no thread of its own: main's thread is the
// worker, and it works while it waits. A wait therefore *serves* its pool
// rather than merely blocking on it — the uniform rule is that a `waitfor`
// serves its own pool's work except activations of the actor doing the
// waiting, so a waiting actor's mailbox stays stalled (serialization is
// preserved) while main, which has no mailbox, serves everything placed on
// its pool. Blocking is the degenerate case of an empty queue.
package salvo

import kotlin.concurrent.withLock

/** An actor body: state plus one entry point per kind of delivery. */
interface SalvoActor {
    /** A user message (a `send fn` invocation). */
    fun handle(ctx: SalvoCtx, msg: Any?)

    /** A reply delivery: the slot names the parked continuation. */
    fun resume(ctx: SalvoCtx, slot: Long, value: Any?)

    /**
     * [addr-routable] [wire-format] Decodes a reply that arrived over the
     * wire for the continuation parked at [slot]: only the actor knows the
     * answer's type. `null` when nothing is parked there or the bytes are
     * malformed. The `Boolean` half says whether a value was decoded at all,
     * since `null` is itself a value (`None`).
     */
    fun decodeReply(slot: Long, payload: ByteArray): Pair<Boolean, Any?> = Pair(false, null)
}

/**
 * [addr-routable] The routable identity of an actor: the node hosting it, its
 * index there, and the unguessable bits minted at its spawn [addr-capability].
 */
data class SalvoRemoteRef(val node: Long, val actor: Long, val bits: Long)

/** Passed to every activation: the actor's own identity. */
class SalvoCtx(val addr: Int)

private sealed class SalvoEntry {
    /** A user message, and — for one that came over the wire — its sender's node. */
    class User(val msg: Any?, val from: Long?) : SalvoEntry()

    class Reply(val slot: Long, val value: Any?) : SalvoEntry()

    /** [addr-routable] A reply that arrived over the wire, still as bytes. */
    class ReplyRaw(val slot: Long, val bytes: ByteArray) : SalvoEntry()
}

private class SalvoActorState(
    val bound: Int,
    val pool: Int,
    var body: SalvoActor?,
    /** [addr-routable] The node this actor lives on. */
    val node: Long,
    /** [addr-capability] Unguessable bits minted at spawn. */
    val bits: Long,
    /** [addr-routable] `non-null` for a proxy of an actor on another node. */
    val remote: SalvoRemoteRef?,
    /** [wire-format] How a message frame for one of its protocols is decoded. */
    val decode: ((String, ByteArray) -> Pair<Boolean, Any?>)?,
) {
    /** [remote-backpressure] For a proxy: messages the remote mailbox has room for. */
    var credits = 0
    /** [remote-backpressure] For a hosted actor: credits held by remote senders. */
    var granted = 0
    val queue = ArrayDeque<SalvoEntry>()
    var userLen = 0
    var gate: Long? = null
    var running = false
    var dead = false

    /**
     * The host's account of the fault that killed it, kept so a watch
     * registered *after* the death answers what the earlier watchers got.
     */
    var exitReason: String? = null

    /**
     * [actor-watch] Registered death watches: the token to fulfil and the
     * **builder** generated code handed over with it, which turns the reason
     * into the language's `Exit` value. The runtime cannot construct a Salvo
     * class, so the watch site supplies the constructor.
     */
    val watchers = mutableListOf<Pair<SalvoReply, (String) -> Any?>>()

    /**
     * [actor-on-idle] Reply tokens aimed at this actor that nobody has
     * discharged — the continuations it is still owed. A token whose holder
     * died stays counted, which is the honest answer: the obligation is
     * genuinely lost.
     */
    var owed = 0
}

private class SalvoWaiterState(val pool: Int) {
    var value: Any? = null
    var filled = false
    /** [wire-format] How a reply arriving over the wire for this waiter is decoded. */
    var decode: ((ByteArray) -> Pair<Boolean, Any?>)? = null

    /**
     * [waitfor-pump] While this waiter is parked: whether a frame is sitting
     * on it, and the actor whose activation that frame is, if it is one
     * ([parkedActor] is null for main and for a task). What the deadlock
     * report reads to name the **occupied** actors — the ones whose mailbox
     * is stalled by a wait nested inside an activation.
     */
    var parked = false
    var parkedActor: Int? = null
}

/**
 * [main-pool] [waitfor-pump] Where a thread is: the pool it works for, the
 * actor whose activation it is currently inside (`null` on main, inside a task
 * and between activations), and whether it is inside a frame the scheduler
 * counts in `active` at all. The pool is what an `on`-less spawn or mint
 * inherits; the actor is the one thing a wait must not serve; [frame]
 * distinguishes main's own thread from a task running on the main pool, which
 * is what a wait has to know to book itself correctly.
 */
private class SalvoHere(val pool: Int, val actor: Int?, val frame: Boolean = false)

/**
 * [task-mint] What a pool owns besides its worker threads: a queue of
 * detached tasks, and the sink an uncaught fault on it is reported to
 * [pool-fault-sink] (`null` is the named runtime report).
 */
private class SalvoPoolState(
    /** [addr-routable] The node this pool's work belongs to. */
    val node: Long,
) {
    /** Tasks whose answer has arrived, in the order it arrived. */
    val tasks = ArrayDeque<Pair<(Any?) -> Unit, Any?>>()
    var sinkAddr: Int? = null
    var sinkBuild: ((String) -> Any?)? = null

    /**
     * [actor-on-idle] Undischarged tokens that belong to this pool without
     * belonging to an actor on it: a task waiting for its answer, and the
     * token a frame working for this pool is parked on.
     */
    var owed = 0
}

/**
 * The scheduler: one shared lock (its own monitor) over all state, pool
 * worker threads, and the waiter bridge for `main`.
 */
object SalvoSched {
    /**
     * [main-pool] The pool main is the single worker of. It never gets a
     * worker thread: main's own thread runs its work, while it waits.
     */
    const val MAIN_POOL = 0

    private val lock = java.util.concurrent.locks.ReentrantLock()
    private val cv = lock.newCondition()
    private val actors = mutableListOf<SalvoActorState>()
    private val waiters = mutableListOf<SalvoWaiterState>()
    /** [addr-routable] This process's node identity, and every node it hosts. */
    private val nodeId: Long = randomLong()
    private val hostedNodes = mutableListOf(nodeId)
    /** [addr-routable] Imported identities → the local proxy entry for each. */
    private val proxies = HashMap<SalvoRemoteRef, Int>()
    /** [addr-routable] Where a node's frames go: its encoded endpoint. */
    private val routes = HashMap<Long, ByteArray>()
    /** [addr-routable] The outbound hooks, one per hosted node. */
    private val wires = HashMap<Long, (ByteArray, ByteArray) -> Unit>()
    /** [addr-routable] Tasks whose token crossed the wire, by key. */
    private val exportedTasks = HashMap<Long, Triple<Int, (Any?) -> Unit, (ByteArray) -> Pair<Boolean, Any?>>>()
    /** [addr-routable] Frames (from, to, bytes) for nodes with no route or wire yet. */
    private val parkedFramesOut = mutableListOf<Triple<Long, Long, ByteArray>>()
    /** [node-group] Per hosted node: group name, own encoded endpoint, and the events sink with its three builders. */
    private class GroupState {
        var name = ""
        var endpoint = ByteArray(0)
        var sink: Int? = null
        var hello: ((Long, ByteArray, List<Pair<String, String>>) -> Any?)? = null
        var gone: ((Long) -> Any?)? = null
        var intro: ((List<ByteArray>) -> Any?)? = null
    }
    private val groups = HashMap<Long, GroupState>()
    /** [protocol-hash] Every peer's protocol table, by node. */
    private val peerProtocols = HashMap<Long, Map<String, String>>()
    /** [protocol-hash] This program's own table, registered at start-up. */
    private var protocols: List<Pair<String, String>> = emptyList()
    /** [actor-group] What each hosted node publishes by name: identity, and the sink + builders. */
    private class Published(val ref: SalvoRemoteRef, val sink: Int?, val named: ((Long) -> Any?)?, val members: ((Long, List<SalvoRemoteRef>) -> Any?)?)
    private val published = HashMap<Long, HashMap<String, Published>>()
    /** [actor-group] What peers have published: (node, name) → identity. */
    private val peerNames = HashMap<Pair<Long, String>, SalvoRemoteRef>()
    /** [route-stub] Per local group replica: its mirrored member set, what a `route(group)` stub reads. */
    private val views = HashMap<Int, List<Int>>()
    /** Frames staged under the lock, sent once it is released. */
    private val outbox = ThreadLocal.withInitial { mutableListOf<Triple<ByteArray, ByteArray, (ByteArray, ByteArray) -> Unit>>() }
    // [main-pool] Pool 0 exists from the start and belongs to main.
    private val pools = mutableListOf(SalvoPoolState(nodeId))
    private var nextSlot = 0L
    private var active = 0

    /**
     * [waitfor-pump] Of the [active] frames, the ones parked in a wait: an
     * activation or a task whose frame is alive on some thread's stack but
     * which cannot proceed until its token arrives. It still holds its actor's
     * `running` flag — so its mailbox is stalled and nobody else will serve it
     * — which is why a parked frame is *not* progress and must not hide a
     * deadlock. `active - parkedFrames` is the number of frames that can still
     * get somewhere on their own.
     */
    private var parkedFrames = 0

    /**
     * [waitfor-pump] How deep main's own thread is in a wait. main is the one
     * thread that runs program code without being a frame the scheduler
     * counts, so while it is *not* waiting it is progress the scheduler cannot
     * see, and no deadlock may be declared.
     */
    private var mainWaits = 0

    /**
     * [actor-on-idle] Registered quiescence hooks: the pool whose obligations
     * the answer reports, the token to fulfil, and the builder for its
     * payload. Taken as a whole when the scheduler settles — every
     * registration is a one-shot.
     */
    private val idleHooks = mutableListOf<Triple<Int, SalvoReply, (Int, Int) -> Any?>>()

    /**
     * [time-timer] Registered deadlines, each a monotonic reading with the
     * token to fulfil when it passes and the builder for the `Fired` payload.
     * Unordered, exactly as on the Rust side: a program registers few
     * deadlines at a time, so one scan per wake beats keeping a heap ordered
     * under the scheduler's own lock.
     */
    private val timers = mutableListOf<Triple<Long, SalvoReply, (Long) -> Any?>>()

    /**
     * [time-timer] Whether the deadline thread is running. Started by the
     * first [after], so a program that never sets a timer has no timer thread
     * — and one that does has exactly one, never a thread per timer.
     */
    private var timerThread = false
    /**
     * [threadsafe-platform] Outside sources of work the scheduler cannot see:
     * a host thread that may send at any moment (a transport's socket
     * reader). Bumped by [externalBegin]/[externalEnd] from host code. While
     * one is registered the program is neither quiescent nor deadlocked,
     * exactly as with a pending timer — the [actor-on-idle] caveat made a fact
     * the runtime is told.
     */
    private var externals = 0
    private val here = ThreadLocal.withInitial { SalvoHere(MAIN_POOL, null) }

    /** [threadsafe-platform] A host thread that may inject work is open. */
    fun externalBegin() {
        lock.withLock { externals += 1 }
    }

    /** [threadsafe-platform] …and is gone; wakes waiters so idleness can settle. */
    fun externalEnd() {
        lock.withLock {
            if (externals > 0) externals -= 1
            cv.signalAll()
        }
    }

    /** Creates a pool of [n] daemon worker threads and answers its id. */
    fun pool(n: Int): Int = poolWithSink(n, null, null)

    /**
     * [pool-fault-sink] The same, with an actor to report uncaught faults to:
     * the addr and the builder that turns the host's reason into the
     * language's `Fault` value (the runtime cannot construct one, exactly as
     * with `Exit` [actor-watch]).
     */
    fun poolWithSink(
        n: Int,
        sinkAddr: Int?,
        sinkBuild: ((String) -> Any?)?,
    ): Int {
        val id =
            lock.withLock {
                val state = SalvoPoolState(pools[currentPool()].node)
                state.sinkAddr = sinkAddr
                state.sinkBuild = sinkBuild
                pools.add(state)
                pools.size - 1
            }
        repeat(n) {
            Thread { worker(id) }.apply {
                isDaemon = true
                start()
            }
        }
        return id
    }

    /**
     * [task-mint] Mints a token whose fulfilment **schedules** [body] on
     * [pool]. No capacity is reserved and no queue can be full: a task has no
     * mailbox, which is why a task mint contributes no deadlock edge.
     */
    fun mintTask(
        pool: Int,
        decode: (ByteArray) -> Pair<Boolean, Any?> = { _ -> Pair(false, null) },
        body: (Any?) -> Unit,
    ): SalvoReply =
        lock.withLock {
            nextSlot += 1
            pools[pool].owed += 1
            SalvoReply(SalvoTargetTask(pool, body, decode), nextSlot)
        }

    /**
     * [main-pool] The pool the calling thread works for — what a spawn or a
     * mint with no `on` clause inherits. Main's thread answers [MAIN_POOL].
     */
    fun currentPool(): Int = here.get().pool

    /**
     * [waitfor-dedicated] A pool of exactly one thread, for work that may
     * occupy its thread until an answer arrives. Identical to `pool(1)` at
     * run time — what makes it different is static: the language types it as
     * a `Dedicated Pool` and the `on` clause consumes it, so a dedicated
     * thread has exactly one occupant.
     */
    fun thread(): Int = pool(1)

    /** Spawns an actor on a pool. The queue bound is explicit and required. */
    fun spawn(
        pool: Int,
        bound: Int,
        body: SalvoActor,
        decode: ((String, ByteArray) -> Pair<Boolean, Any?>)? = null,
    ): Int =
        lock.withLock {
            actors.add(SalvoActorState(bound, pool, body, pools[pool].node, randomLong(), null, decode))
            actors.size - 1
        }

    /**
     * Sends a user message. Blocks while the target's queue is full; a
     * send to a dead actor is a silent no-op.
     *
     * [main-pool] One block is a *guaranteed* wedge rather than
     * back-pressure: the main pool has exactly one worker — main's own
     * thread, which serves work only inside a `waitfor` — so a full
     * main-pool mailbox blocked on from that same thread can never drain.
     * Reported by name instead of hung.
     */
    fun send(addr: Int, msg: Any?) {
        lock.withLock {
            while (!actors[addr].dead && actors[addr].userLen >= actors[addr].bound) {
                if (currentPool() == MAIN_POOL && actors[addr].pool == MAIN_POOL) {
                    reportMainPoolWedge(addr)
                }
                cv.await()
            }
            if (actors[addr].dead) {
                return
            }
            // [addr-routable] A proxy has no queue: the typed path
            // (`sendWire`) encodes. Reaching here is an emitter mistake.
            check(actors[addr].remote == null) {
                "internal: an untyped send to a remote proxy (the protocol has no wire form)"
            }
            actors[addr].queue.addLast(SalvoEntry.User(msg, null))
            actors[addr].userLen += 1
            cv.signalAll()
        }
    }

    /**
     * [main-pool] The full-main-pool-mailbox report: a named error, since
     * the only thread that could drain the queue is the one blocked on it.
     */
    private fun reportMainPoolWedge(addr: Int): Nothing {
        System.err.println(
            "salvo: deadlock: the main pool's actor $addr has a full mailbox and the " +
                "only thread that could drain it is the one sending: the main pool has one " +
                "worker, `main` itself, and it serves work only inside a `waitfor` — send " +
                "fewer messages before waiting, raise the handler's `mailbox` capacity, or " +
                "place the actor on a pool of its own",
        )
        kotlin.system.exitProcess(1)
    }

    /**
     * Mints a reply token targeting a actor's parked continuation, and
     * answers the slot beside it: the slot is what generated code keys its
     * parked-continuation table by. A `Pair`, like [waiter], and the mirror
     * of the Rust runtime's `salvo_mint`.
     */
    fun mint(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            nextSlot += 1
            actors[addr].owed += 1
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * Mints a *gated* reply token: until it is delivered, the actor
     * serves nothing else. At most one gate may be outstanding — a second
     * is a fault in the calling activation.
     */
    fun mintGated(addr: Int): Pair<SalvoReply, Long> =
        lock.withLock {
            check(actors[addr].gate == null) { "a gated continuation is already outstanding" }
            nextSlot += 1
            actors[addr].gate = nextSlot
            actors[addr].owed += 1
            Pair(SalvoReply(SalvoTargetProc(addr), nextSlot), nextSlot)
        }

    /**
     * [actor-watch] Registers a death watch: [onExit] is sent the `Exit`
     * [exit] builds when the actor dies. Watching an already-dead actor
     * answers immediately, with the reason its death recorded — so a watch
     * that loses the race to a fast fault is not a watch that never answers.
     */
    fun watch(
        addr: Int,
        onExit: SalvoReply,
        exit: (String) -> Any?,
    ) {
        lock.withLock {
            untrack(onExit)
            if (actors[addr].dead) {
                deliverReply(onExit, exit(actors[addr].exitReason ?: "fault"))
                cv.signalAll()
            } else {
                actors[addr].watchers.add(Pair(onExit, exit))
            }
        }
    }

    /**
     * [actor-on-idle] Registers a quiescence hook: [notify] is sent the `Idle`
     * [idle] builds the moment nothing anywhere can run, reporting what [pool]
     * is still owed. One-shot, exactly as a watch is — delivering the answer is
     * work, which ends the idleness that produced it.
     *
     * The registration itself wakes every worker: the scheduler may *already*
     * be settled, in which case the next thread to look fires the hook.
     */
    fun onIdle(
        pool: Int,
        notify: SalvoReply,
        idle: (Int, Int) -> Any?,
    ) {
        lock.withLock {
            untrack(notify)
            idleHooks.add(Triple(pool, notify, idle))
            cv.signalAll()
        }
    }

    /**
     * [time-timer] Registers a deadline: [done] is sent the `Fired` [fired]
     * builds once at least [delay] nanoseconds have passed, carrying the
     * monotonic reading it fired at.
     *
     * One thread serves every deadline, started on the first registration and
     * parked in a timed wait until the earliest one comes due — the same shape
     * as the Rust backend's, and for the same reason: no thread per timer, no
     * polling. A registration wakes it, since the new deadline may be earlier
     * than the one it is sleeping on.
     *
     * A delay of zero or less fires at the next look rather than immediately:
     * the answer is always a *later* activation, never a call inside `after`.
     */
    fun after(
        delay: Long,
        done: SalvoReply,
        fired: (Long) -> Any?,
    ) {
        lock.withLock {
            // The token is the scheduler's obligation now, exactly as with a
            // watch or an idle hook [actor-on-idle].
            untrack(done)
            val deadline = SalvoTime.monoNanos() + if (delay < 0L) 0L else delay
            timers.add(Triple(deadline, done, fired))
            if (!timerThread) {
                timerThread = true
                val t = Thread { serveTimers() }
                t.isDaemon = true
                t.start()
            }
            cv.signalAll()
        }
    }

    /**
     * [time-timer] The deadline thread: delivers every timer whose deadline
     * has passed, then sleeps until the earliest one left (or until something
     * changes). It never exits — the program ends when main returns
     * [actor-waitfor], and pending timers die with it (the thread is a daemon,
     * so it does not hold the JVM open).
     */
    private fun serveTimers() {
        lock.lock()
        try {
            while (true) {
                val now = SalvoTime.monoNanos()
                val due = timers.filter { it.first <= now }
                if (due.isNotEmpty()) {
                    timers.removeAll(due)
                    for ((deadline, done, fired) in due) {
                        deliverReply(done, fired(deadline))
                    }
                    cv.signalAll()
                    continue
                }
                val earliest = timers.minOfOrNull { it.first }
                if (earliest == null) {
                    cv.await()
                } else {
                    cv.awaitNanos(earliest - now)
                }
            }
        } finally {
            lock.unlock()
        }
    }

    /** A waiter: the `waitfor` bridge. Answers (token, waiter id). */
    fun waiter(): Pair<SalvoReply, Int> =
        lock.withLock {
            val pool = currentPool()
            waiters.add(SalvoWaiterState(pool))
            nextSlot += 1
            pools[pool].owed += 1
            Pair(SalvoReply(SalvoTargetWaiter(waiters.size - 1), nextSlot), waiters.size - 1)
        }

    /**
     * [waitfor-pump] Blocks the calling thread until the waiter's token is
     * sent, and answers the value — *serving this thread's pool while it
     * waits* (everything on it except the waiting actor's own activations,
     * which stay stalled). For main, whose pool has no other worker, that is
     * what runs main-pool work at all; where the queue is empty the wait is a
     * plain block. If nothing can run while this frame waits, reports the
     * deadlock instead of hanging — including when the waiting frame is an
     * **occupied actor**, whose own mailbox its wait has stalled.
     */
    fun awaitReply(wid: Int): Any? {
        val spot = here.get()
        lock.lock()
        try {
            // This frame is parked for the whole call, including across the
            // jobs the pump runs below: each of those books itself in `active`
            // on its own, so `active - parkedFrames` stays the count of frames
            // that can still proceed.
            enterWait(spot, wid)
            while (true) {
                if (waiters[wid].filled) {
                    waiters[wid].filled = false
                    leaveWait(spot, wid)
                    return waiters[wid].value
                }
                // [waitfor-pump] Detached tasks are what the rule names
                // first, and they are served whoever is waiting; activations
                // are served except the waiter's own.
                if (pools[spot.pool].tasks.isNotEmpty()) {
                    runTask(spot.pool)
                    continue
                }
                val job = pick(spot.pool, spot.actor)
                if (job != null) {
                    runJob(job.first, job.second)
                    continue
                }
                // [actor-on-idle] Nothing to run is exactly the event the hooks
                // are registered for, and firing one *is* progress — so it comes
                // before the deadlock report, which is what firing nothing
                // leaves.
                if (fireIdle()) {
                    continue
                }
                if (stuck()) {
                    reportDeadlock(spot.actor)
                }
                cv.await()
            }
        } finally {
            lock.unlock()
        }
    }

    /**
     * [waitfor-pump] Books the calling frame as parked on [wid]: an activation
     * or a task counts out of the frames that can still proceed, and main's own
     * thread — which the scheduler never counts as a frame — records that it is
     * inside a wait at all, since main running program code is progress nothing
     * else can see.
     */
    private fun enterWait(
        spot: SalvoHere,
        wid: Int,
    ) {
        waiters[wid].parked = true
        waiters[wid].parkedActor = spot.actor
        if (spot.frame) {
            parkedFrames += 1
        } else if (spot.pool == MAIN_POOL) {
            mainWaits += 1
        }
    }

    /**
     * The exact reverse, on every way out of a wait. Clamped at zero, so an
     * unbalanced pair cannot turn the counts into a permanent "everything is
     * stuck".
     */
    private fun leaveWait(
        spot: SalvoHere,
        wid: Int,
    ) {
        waiters[wid].parked = false
        waiters[wid].parkedActor = null
        if (spot.frame) {
            parkedFrames = clamp(parkedFrames - 1)
        } else if (spot.pool == MAIN_POOL) {
            mainWaits = clamp(mainWaits - 1)
        }
    }

    internal fun sendReply(reply: SalvoReply, value: Any?) {
        lock.withLock {
            deliverReply(reply, value)
            cv.signalAll()
        }
    }

    /** Delivery under the lock: reserved capacity, no-op to the dead. */
    private fun deliverReply(reply: SalvoReply, value: Any?) {
        // [actor-on-idle] The obligation is met here, whatever the target does
        // with the value — including a no-op delivery to the dead.
        untrack(reply)
        when (val target = reply.target) {
            is SalvoTargetWaiter -> {
                waiters[target.wid].value = value
                waiters[target.wid].filled = true
            }
            is SalvoTargetProc -> {
                if (actors[target.addr].dead) {
                    return
                }
                actors[target.addr].queue.addLast(SalvoEntry.Reply(reply.slot, value))
            }
            // [task-mint] The answer schedules the task. Nothing to check: a
            // task has no mailbox to fill and no death to be a no-op for. A
            // body already taken means the token crossed the wire.
            is SalvoTargetTask -> {
                val body = target.body
                if (body != null) {
                    target.body = null
                    pools[target.pool].tasks.addLast(Pair(body, value))
                }
            }
            // [addr-routable] An untyped reply to a remote token: unreachable,
            // since a value with no wire form is never owed to one.
            is SalvoTargetRemote -> error("internal: an untyped reply to a remote token")
        }
    }

    /** The first deliverable entry for an actor, honouring the gate. */
    private fun deliverable(p: SalvoActorState): Int? {
        if (p.running || p.dead) {
            return null
        }
        val gate = p.gate ?: return if (p.queue.isEmpty()) null else 0
        val at = p.queue.indexOfFirst {
            (it is SalvoEntry.Reply && it.slot == gate) || (it is SalvoEntry.ReplyRaw && it.slot == gate)
        }
        return if (at < 0) null else at
    }

    /**
     * True when no work is *queued* anywhere: no actor has a deliverable
     * entry, no pool has a scheduled task, no deadline is pending, and no
     * parked frame has an answer sitting in its slot.
     *
     * [waitfor-pump] That last clause is a queue too, even though it looks
     * like a variable: a fulfilled waiter slot is work whose *pickup is the
     * waiting thread itself*, which will take it at the top of its next pass.
     * Between the delivery and the pickup the frame is still booked as parked,
     * so without this clause a thread that looked in that window would call a
     * program stuck one instant before it proceeds.
     *
     * [time-timer] A pending deadline counts as work on its way: the timer
     * thread will deliver it, so a program waiting for a fire is neither
     * quiescent ([actor-on-idle]) nor deadlocked — it is waiting for time to
     * pass, which is the one thing that happens without anybody running.
     */
    private fun quiet(): Boolean =
        actors.all { deliverable(it) == null } &&
            pools.all { it.tasks.isEmpty() } &&
            timers.isEmpty() &&
            externals == 0 &&
            waiters.none { it.parked && it.filled }

    /**
     * True when nothing can ever run again without outside input: no
     * activation is running and nothing is queued.
     *
     * [actor-on-idle] What the quiescence hook fires on. A frame parked in a
     * `waitfor` counts as running here, so idleness does not fire while any
     * wait is in flight — the stated caveat of the rule.
     */
    private fun idle(): Boolean = active == 0 && quiet()

    /**
     * True when nothing can ever run again *and* somebody is waiting for
     * something — the deadlock condition, which is weaker than [idle] in
     * exactly one way: a frame **parked in a wait** is not progress.
     *
     * [waitfor-pump] Every clause is a thread that could still get somewhere:
     * `active - parkedFrames > 0` is a frame running rather than parked (a body
     * between two waits, or a sender blocked on a full mailbox, which will
     * proceed when the mailbox drains); `mainWaits == 0` is main's thread
     * running program code, which the scheduler does not count as a frame and
     * therefore cannot see; `!quiet()` is something queued for whoever runs
     * next. With all of them false, every thread the scheduler knows about is
     * parked on an answer and nothing is queued to produce one. The remaining
     * blind spot is stated with [actor-on-idle] and is the same one the report
     * has always had — a platform handler with a thread of its own can inject
     * work the scheduler never saw.
     */
    private fun stuck(): Boolean = active == parkedFrames && mainWaits > 0 && quiet()

    /**
     * [actor-on-idle] Marks one token as no longer outstanding, against
     * whatever it was owed by: the actor it targets, the pool a task will run
     * on, or the pool of the frame parked on it. Clamped at zero, so a double
     * release cannot go negative.
     */
    private fun release(target: SalvoTarget) {
        when (target) {
            is SalvoTargetProc -> actors[target.addr].owed = clamp(actors[target.addr].owed - 1)
            is SalvoTargetTask -> pools[target.pool].owed = clamp(pools[target.pool].owed - 1)
            is SalvoTargetWaiter -> {
                val pool = waiters[target.wid].pool
                pools[pool].owed = clamp(pools[pool].owed - 1)
            }
            // [addr-routable] Owed on the origin node; nothing here.
            is SalvoTargetRemote -> {}
        }
    }

    private fun clamp(n: Int): Int = if (n < 0) 0 else n

    /**
     * [actor-on-idle] Hands a token over to the scheduler: it stops counting as
     * an obligation the program owes, because the scheduler is now the one who
     * will answer it. Used by [watch] and [onIdle], which is why a steady-state
     * program with registrations outstanding still reports zero.
     */
    private fun untrack(reply: SalvoReply) {
        if (reply.tracked) {
            reply.tracked = false
            release(reply.target)
        }
    }

    /**
     * [actor-on-idle] What an `Idle` payload says about a pool: how many actors
     * placed there have a gated mailbox, and how many reply tokens aimed at
     * work there nobody has discharged. Both zero is "done"; either non-zero is
     * "idle and still owed something".
     */
    private fun parked(pool: Int): Pair<Int, Int> {
        val gates = actors.count { it.pool == pool && it.gate != null && !it.dead }
        val tokens = actors.filter { it.pool == pool }.sumOf { it.owed } + pools[pool].owed
        return Pair(gates, tokens)
    }

    /**
     * [actor-on-idle] Fires every registered quiescence hook, if the scheduler
     * has settled. Answers whether anything fired — which is *progress*, so a
     * caller about to declare a deadlock has to look again first.
     *
     * Registrations are one-shots and all of them fire together: quiescence is
     * a property of the whole scheduler, so there is no order in which one hook
     * could see it and another not.
     */
    private fun fireIdle(): Boolean {
        if (idleHooks.isEmpty() || !idle()) {
            return false
        }
        val hooks = idleHooks.toList()
        idleHooks.clear()
        for ((pool, notify, build) in hooks) {
            val (gates, tokens) = parked(pool)
            deliverReply(notify, build(gates, tokens))
        }
        cv.signalAll()
        return true
    }

    /**
     * [waitfor-pump] The next job a thread working for [pool] may run:
     * [exclude] is the actor whose own activation is waiting, which a wait
     * must never serve — re-entering an actor mid-activation is precisely
     * what serialization exists to prevent. A pool worker excludes nothing.
     */
    private fun pick(
        pool: Int,
        exclude: Int?,
    ): Pair<Int, Int>? =
        actors.withIndex().firstNotNullOfOrNull { (i, p) ->
            if (p.pool != pool || i == exclude) null else deliverable(p)?.let { Pair(i, it) }
        }

    /**
     * The deadlock report [actor-watch] [waitfor-pump]: nothing can run while a
     * frame waits, so nothing can ever change — a named error instead of a
     * silent hang. [waiter] names the frame that is waiting, which since
     * [waitfor-effect] need not be main.
     *
     * The two lists are the two ways a mailbox comes to be unservable, and a
     * diagnosis starts by reading them: an actor **parked in a wait** holds its
     * own `running` flag, so *nothing* of its mailbox is delivered by anybody
     * until its token arrives; a **gated** actor serves only the reply it is
     * waiting for.
     */
    private fun reportDeadlock(waiter: Int?): Nothing {
        val occupied = waiters.filter { it.parked && it.parkedActor != null }.map { "actor ${it.parkedActor}" }
        val gated =
            actors.withIndex().filter { it.value.gate != null && !it.value.dead }.map { "actor ${it.index}" }
        val who = if (waiter == null) "main" else "actor $waiter"
        val clauses = mutableListOf<String>()
        if (occupied.isNotEmpty()) {
            clauses.add("parked in a wait: ${occupied.joinToString(", ")}")
        }
        if (gated.isNotEmpty()) {
            clauses.add("parked gates: ${gated.joinToString(", ")}")
        }
        val detail = if (clauses.isEmpty()) "" else " (${clauses.joinToString("; ")})"
        System.err.println("salvo: deadlock: nothing can run while $who waits$detail")
        kotlin.system.exitProcess(1)
    }

    /**
     * Runs one activation to completion. Called with the lock held and
     * answers with it held, releasing it for the body itself: a fault is
     * caught at this boundary and becomes the actor's death. Both callers —
     * a pool worker and a `waitfor` pumping its own pool [waitfor-pump] — go
     * through here, so an activation means the same thing whichever thread
     * runs it.
     */
    private fun runJob(
        addr: Int,
        at: Int,
    ) {
        val p = actors[addr]
        val entry = p.queue.removeAt(at)
        if (entry is SalvoEntry.User) {
            p.userLen -= 1
            // [remote-backpressure] A remote sender's message left the queue:
            // grant that node one credit back for this actor.
            val from = entry.from
            if (from != null) grantCredit(addr, from, 1)
        }
        if (entry is SalvoEntry.Reply && p.gate == entry.slot) {
            p.gate = null
        }
        if (entry is SalvoEntry.ReplyRaw && p.gate == entry.slot) {
            p.gate = null
        }
        val body = p.body
        p.body = null
        p.running = true
        active += 1
        cv.signalAll() // a user entry left the queue
        lock.unlock()
        // [remote-backpressure] A credit granted for the dequeued entry was
        // staged under the lock; it goes out now that the lock is released.
        flushOut()

        // The activation runs *here*: an ambient mint inside it inherits this
        // pool, and a nested wait must not serve this actor [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(p.pool, addr, frame = true))
        val ctx = SalvoCtx(addr)
        var fault: String? = null
        try {
            when (entry) {
                is SalvoEntry.User -> body!!.handle(ctx, entry.msg)
                is SalvoEntry.Reply -> body!!.resume(ctx, entry.slot, entry.value)
                // [addr-routable] Decoded here, with the body in hand and the
                // lock released; a malformed answer is dropped.
                is SalvoEntry.ReplyRaw -> {
                    val (ok, value) = body!!.decodeReply(entry.slot, entry.bytes)
                    if (ok) body.resume(ctx, entry.slot, value)
                }
            }
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        p.running = false
        active -= 1
        // A local `val`, because a captured `var` does not smart-cast
        // inside a lambda and the `Exit` builder wants a `String`.
        val reason = fault
        if (reason == null) {
            p.body = body
        } else {
            p.dead = true
            p.exitReason = reason
            p.queue.clear()
            p.userLen = 0
            p.gate = null
            val watchers = p.watchers.toList()
            p.watchers.clear()
            for ((w, exit) in watchers) {
                deliverReply(w, exit(reason))
            }
            // [pool-fault-sink] The net under supervision: a death nobody was
            // watching still reaches the pool's sink, or the named report.
            if (watchers.isEmpty()) {
                reportFault(p.pool, reason)
            }
        }
        cv.signalAll()
    }

    /**
     * [task-mint] Runs one detached task to completion, with the same lock
     * discipline and fault boundary as an activation: the lock is released for
     * the body, and a fault is caught here. A task has no identity, so there
     * is nothing to mark dead and nobody to notify — the fault goes to the
     * pool's sink [pool-fault-sink], or to the named report when it has none.
     */
    private fun runTask(pool: Int) {
        val job = pools[pool].tasks.removeFirstOrNull() ?: return
        active += 1
        lock.unlock()

        // A task belongs to no actor, so a nested wait inside it may serve
        // every activation on the pool [waitfor-pump].
        val spot = here.get()
        here.set(SalvoHere(pool, null, frame = true))
        var fault: String? = null
        try {
            job.first(job.second)
        } catch (t: Throwable) {
            fault = t.message ?: t.javaClass.simpleName
        } finally {
            here.set(spot)
            lock.lock()
        }
        active -= 1
        val reason = fault
        if (reason != null) {
            reportFault(pool, reason)
        }
        cv.signalAll()
    }

    /**
     * [pool-fault-sink] Where an uncaught fault on a pool goes: a message to
     * the pool's sink actor if it has one, else a named report on stderr. A
     * fault that cannot be delivered (a dead sink) falls back to the report,
     * since the alternative is losing it silently.
     */
    private fun reportFault(
        pool: Int,
        reason: String,
    ) {
        val addr = pools[pool].sinkAddr
        val build = pools[pool].sinkBuild
        if (addr != null && build != null && !actors[addr].dead) {
            // Enqueued past the bound deliberately: a fault report must not
            // block the faulting thread, and dropping it would lose the one
            // thing the sink exists for.
            actors[addr].queue.addLast(SalvoEntry.User(build(reason), null))
            actors[addr].userLen += 1
            return
        }
        System.err.println("salvo: an uncaught fault on pool $pool: $reason")
    }

    // ==================================================================
    // [addr-routable] [addr-capability] [remote-backpressure] Across machines
    // — the Rust runtime's wire section, mirrored; the frame formats are
    // documented there and are byte-identical here.
    // ==================================================================

    /** [addr-routable] This process's node identity. */
    fun nodeId(): Long = lock.withLock { nodeId }

    /** [addr-routable] The node the current pool belongs to. */
    fun hereNode(): Long = lock.withLock { pools[currentPool()].node }

    /** [addr-routable] Hosts a fresh virtual node in this process. */
    fun newNode(): Long =
        lock.withLock {
            val id = randomLong()
            hostedNodes.add(id)
            id
        }

    /** [addr-routable] A pool of [n] workers belonging to [node]. */
    fun poolAt(node: Long, n: Int): Int {
        val id =
            lock.withLock {
                pools.add(SalvoPoolState(node))
                pools.size - 1
            }
        repeat(n) {
            Thread { worker(id) }.apply {
                isDaemon = true
                start()
            }
        }
        return id
    }

    /** [addr-routable] The routable identity of a local index. */
    fun addrIdentity(addr: Int): SalvoRemoteRef =
        lock.withLock {
            val a = actors[addr]
            a.remote ?: SalvoRemoteRef(a.node, addr.toLong(), a.bits)
        }

    /**
     * [addr-routable] [addr-capability] A decoded identity as a local index:
     * the actor itself when its node is hosted here and the bits match (a
     * forged identity answers a dead entry), a proxy otherwise — created once,
     * with an OPEN frame asking the host for credits.
     */
    fun importAddr(r: SalvoRemoteRef): Int {
        val idx =
            lock.withLock {
                val node = pools[currentPool()].node
                // An identity of *this* node is the actor itself; any other
                // node — hosted here or not — is reached through a proxy.
                if (r.node == node) {
                    val i = r.actor.toInt()
                    if (i in actors.indices && actors[i].remote == null && actors[i].bits == r.bits) {
                        return i
                    }
                    return deadEntry()
                }
                proxies[r]?.let { return it }
                actors.add(SalvoActorState(0, 0, null, r.node, r.bits, r, null))
                val idx = actors.size - 1
                proxies[r] = idx
                val out = java.io.ByteArrayOutputStream()
                val d = java.io.DataOutputStream(out)
                d.writeByte(3); d.writeLong(r.node); d.writeLong(r.actor); d.writeLong(r.bits); d.writeLong(node)
                routeFrame(node, r.node, out.toByteArray())
                cv.signalAll()
                idx
            }
        flushOut()
        return idx
    }

    private fun deadEntry(): Int {
        val a = SalvoActorState(0, 0, null, nodeId, 0, null, null)
        a.dead = true
        a.exitReason = "unknown identity"
        actors.add(a)
        return actors.size - 1
    }

    /** [addr-routable] Whether an index is a proxy of an actor elsewhere. */
    fun isRemote(addr: Int): Boolean = lock.withLock { actors[addr].remote != null }

    /** [addr-routable] Registers where a node's frames go. */
    fun addRoute(node: Long, endpoint: ByteArray) {
        lock.withLock {
            routes[node] = endpoint
            val parked = ArrayList(parkedFramesOut)
            parkedFramesOut.clear()
            for ((from, n, f) in parked) routeFrame(from, n, f)
            cv.signalAll()
        }
        flushOut()
    }

    /** [addr-routable] Binds the outbound hook of the current node. */
    /** [net-connect] Whether the current node's outbound hook is bound — what `connect` checks first. */
    fun connected(): Boolean = lock.withLock { wires.containsKey(pools[currentPool()].node) }

    fun setWire(hook: (ByteArray, ByteArray) -> Unit) {
        lock.withLock {
            wires[pools[currentPool()].node] = hook
            val parked = ArrayList(parkedFramesOut)
            parkedFramesOut.clear()
            for ((from, n, f) in parked) routeFrame(from, n, f)
            cv.signalAll()
        }
        flushOut()
    }

    /** Stages a frame from [from] for [to] under the lock; [flushOut] sends it once released. */
    private fun routeFrame(from: Long, to: Long, frame: ByteArray) {
        val ep = routes[to]
        val hook = wires[from]
        if (ep != null && hook != null) {
            outbox.get().add(Triple(ep, frame, hook))
        } else {
            parkedFramesOut.add(Triple(from, to, frame))
        }
    }

    private fun flushOut() {
        val staged = outbox.get()
        if (staged.isEmpty()) return
        val copy = ArrayList(staged)
        staged.clear()
        for ((ep, frame, hook) in copy) hook(ep, frame)
    }

    /** [remote-backpressure] Grants [n] credits to node [from] for hosted actor [addr]. */
    private fun grantCredit(addr: Int, from: Long, n: Int) {
        val a = actors[addr]
        a.granted += n
        val out = java.io.ByteArrayOutputStream()
        val d = java.io.DataOutputStream(out)
        d.writeByte(2); d.writeLong(from); d.writeLong(a.node); d.writeLong(addr.toLong()); d.writeLong(a.bits); d.writeInt(n)
        routeFrame(a.node, from, out.toByteArray())
    }

    /**
     * [addr-routable] [wire-format] The typed send: a local mailbox as any
     * send, or — for a proxy — encoded with its protocol hash and routed,
     * after waiting for a credit [remote-backpressure].
     */
    fun <M> sendWire(addr: Int, msg: M, proto: String, codec: WireCodec<M>) {
        val r = lock.withLock { actors[addr].remote }
        if (r == null) {
            send(addr, msg)
            return
        }
        val from =
            lock.withLock {
                while (!actors[addr].dead && actors[addr].credits == 0) cv.await()
                if (actors[addr].dead) return
                actors[addr].credits -= 1
                // On a proxy, `granted` counts what is in flight (what `pending` reads).
                actors[addr].granted += 1
                pools[currentPool()].node
            }
        // Encoded with the lock released (mirroring Rust, where the lock is
        // not reentrant and an `Addr` in the payload asks the scheduler).
        val out = WireOut()
        out.u8(0); out.i64(r.node); out.i64(r.actor); out.i64(r.bits); out.i64(from)
        out.raw(proto.toByteArray(Charsets.US_ASCII))
        codec.enc(msg, out)
        val frame = out.toBytes().toByteArray()
        lock.withLock { routeFrame(from, r.node, frame) }
        flushOut()
    }

    /** [remote-backpressure] A proxy's credit balance, or `null` for a local actor. */
    fun credits(addr: Int): Int? = lock.withLock { if (actors[addr].remote != null) actors[addr].credits else null }

    /**
     * [addr-routable] [wire-format] The typed reply: a token that came over
     * the wire is answered with a REPLY frame; a local one delivers as before.
     */
    fun <T> replyWire(reply: SalvoReply, value: T, codec: WireCodec<T>) {
        val target = reply.target
        if (target is SalvoTargetRemote) {
            val out = WireOut()
            out.u8(1); out.i64(target.node); out.u8(target.kind); out.i64(target.id); out.i64(reply.slot); out.i64(target.bits)
            codec.enc(value, out)
            val frame = out.toBytes().toByteArray()
            lock.withLock { routeFrame(pools[currentPool()].node, target.node, frame) }
            flushOut()
        } else {
            sendReply(reply, value)
        }
    }

    /** [addr-routable] The wire form of a reply token. Exporting a task moves its body aside. */
    fun replyExport(reply: SalvoReply): LongArray =
        lock.withLock {
            when (val t = reply.target) {
                is SalvoTargetProc -> {
                    val a = actors[t.addr]
                    longArrayOf(a.node, 0, t.addr.toLong(), reply.slot, a.bits)
                }
                is SalvoTargetWaiter -> longArrayOf(pools[waiters[t.wid].pool].node, 1, t.wid.toLong(), reply.slot, 0)
                is SalvoTargetTask -> {
                    val body = t.body
                    if (body != null) {
                        t.body = null
                        exportedTasks[reply.slot] = Triple(t.pool, body, t.decode)
                    }
                    longArrayOf(pools[t.pool].node, 2, reply.slot, reply.slot, 0)
                }
                is SalvoTargetRemote -> longArrayOf(t.node, t.kind.toLong(), t.id, reply.slot, t.bits)
            }
        }

    /** [addr-routable] A reply token decoded from the wire. */
    fun replyImport(node: Long, kind: Int, id: Long, slot: Long, bits: Long): SalvoReply =
        lock.withLock {
            val target: SalvoTarget =
                if (node == pools[currentPool()].node) {
                    when (kind) {
                        0 -> SalvoTargetProc(id.toInt())
                        1 -> SalvoTargetWaiter(id.toInt())
                        else -> SalvoTargetRemote(node, kind, id, bits)
                    }
                } else {
                    SalvoTargetRemote(node, kind, id, bits)
                }
            SalvoReply(target, slot).also { it.tracked = false }
        }

    /** [addr-routable] Registers how a waiter's reply is decoded off the wire. */
    fun waiterDecoder(wid: Int, decode: (ByteArray) -> Pair<Boolean, Any?>) {
        lock.withLock { waiters[wid].decode = decode }
    }

    /** [protocol-hash] Registers this program's protocol table. */
    fun setProtocols(table: List<Pair<String, String>>) {
        lock.withLock { protocols = table }
    }

    /** [node-group] The current node joins group [name] at [endpoint]. */
    fun setGroup(name: String, endpoint: ByteArray) {
        lock.withLock {
            val g = groups.getOrPut(pools[currentPool()].node) { GroupState() }
            g.name = name
            g.endpoint = endpoint
        }
    }

    /** [node-group] Where the current node's peer events go, with the three builders. */
    fun watchPeers(
        sink: Int,
        hello: (Long, ByteArray, List<Pair<String, String>>) -> Any?,
        gone: (Long) -> Any?,
        intro: (List<ByteArray>) -> Any?,
    ) {
        lock.withLock {
            val g = groups.getOrPut(pools[currentPool()].node) { GroupState() }
            g.sink = sink
            g.hello = hello
            g.gone = gone
            g.intro = intro
        }
    }

    /** [node-group] Tells peer [to] about [peers] (encoded endpoints): an INTRO frame. */
    fun introduce(to: Long, peers: List<ByteArray>) {
        lock.withLock {
            val node = pools[currentPool()].node
            val out = java.io.ByteArrayOutputStream()
            val d = java.io.DataOutputStream(out)
            d.writeByte(7); d.writeLong(to); d.writeLong(node); d.writeInt(peers.size)
            for (p in peers) { d.writeInt(p.size); d.write(p) }
            routeFrame(node, to, out.toByteArray())
        }
        flushOut()
    }

    private fun namedFrame(to: Long, from: Long, name: String, r: SalvoRemoteRef): ByteArray {
        val out = java.io.ByteArrayOutputStream()
        val d = java.io.DataOutputStream(out)
        d.writeByte(8); d.writeLong(to); d.writeLong(from)
        val nb = name.toByteArray(Charsets.UTF_8)
        d.writeInt(nb.size); d.write(nb)
        d.writeLong(r.node); d.writeLong(r.actor); d.writeLong(r.bits)
        return out.toByteArray()
    }

    /** [actor-group] Publishes [addr] under [name] on the current node; hears of peers publishing the same. */
    fun publish(name: String, addr: Int, sink: Int?, named: ((Long) -> Any?)?, members: ((Long, List<SalvoRemoteRef>) -> Any?)?) {
        val already: List<Long> =
            lock.withLock {
                val node = pools[currentPool()].node
                val a = actors[addr]
                val r = a.remote ?: SalvoRemoteRef(a.node, addr.toLong(), a.bits)
                published.getOrPut(node) { HashMap() }[name] = Published(r, sink, named, members)
                for (to in peerProtocols.keys.toList()) routeFrame(node, to, namedFrame(to, node, name, r))
                cv.signalAll()
                peerNames.keys.filter { it.second == name }.map { it.first }
            }
        flushOut()
        if (sink != null && named != null) {
            for (n in already) enqueueEvent(sink, named(n))
        }
    }

    /** [actor-group] Shares [members] with the replica named [name] on peer [to]: a MEMBERS frame. */
    fun shareMembers(name: String, to: Long, members: List<Int>) {
        lock.withLock {
            val node = pools[currentPool()].node
            val out = java.io.ByteArrayOutputStream()
            val d = java.io.DataOutputStream(out)
            d.writeByte(9); d.writeLong(to); d.writeLong(node)
            val nb = name.toByteArray(Charsets.UTF_8)
            d.writeInt(nb.size); d.write(nb)
            d.writeInt(members.size)
            for (m in members) {
                val a = actors[m]
                val r = a.remote ?: SalvoRemoteRef(a.node, m.toLong(), a.bits)
                d.writeLong(r.node); d.writeLong(r.actor); d.writeLong(r.bits)
            }
            routeFrame(node, to, out.toByteArray())
        }
        flushOut()
    }

    /** [actor-group] [remote-backpressure] `pending(addr)`: queue depth locally, in-flight remotely. */
    fun pending(addr: Int): Int = lock.withLock { val a = actors[addr]; if (a.remote != null) a.granted else a.userLen }

    /** [route-stub] The replica [group] mirrors its member set here after every change. */
    fun viewSet(group: Int, members: List<Int>) { lock.withLock { views[group] = members.toList() } }

    /** [route-stub] The mirrored members of [group], by (node, actor id) — the same order on every node and both backends. */
    fun viewMembers(group: Int): List<Int> = lock.withLock {
        val members = views[group] ?: emptyList()
        members.sortedWith(compareBy({ identityOf(it).node }, { identityOf(it).actor }))
    }

    private fun identityOf(addr: Int): SalvoRemoteRef {
        val a = actors[addr]
        return a.remote ?: SalvoRemoteRef(a.node, addr.toLong(), a.bits)
    }

    /** [route-stub] FNV-1a over the key's canonical bytes, identical to Rust's `salvo_key_hash`. */
    fun keyHash(bytes: ByteArray): Long {
        var h = -3750763034362895579L // 0xcbf29ce484222325
        for (b in bytes) {
            h = h xor (b.toLong() and 0xff)
            h *= 1099511628211L
        }
        return h
    }

    /** [route-stub] A stub whose pick answered `None` yields briefly and asks again. */
    fun parkBriefly() { Thread.sleep(1) }

    private fun enqueueEvent(sink: Int, msg: Any?) {
        lock.withLock {
            if (!actors[sink].dead) {
                actors[sink].queue.addLast(SalvoEntry.User(msg, null))
                actors[sink].userLen += 1
            }
            cv.signalAll()
        }
    }

    private fun handshakeBody(node: Long, kind: Int, to: Long): ByteArray? {
        val g = groups[node] ?: return null
        val out = java.io.ByteArrayOutputStream()
        val d = java.io.DataOutputStream(out)
        d.writeByte(kind); d.writeLong(to); d.writeLong(node)
        val name = g.name.toByteArray(Charsets.UTF_8)
        d.writeInt(name.size); d.write(name)
        d.writeInt(g.endpoint.size); d.write(g.endpoint)
        d.writeInt(protocols.size)
        for ((pname, hash) in protocols) {
            val nb = pname.toByteArray(Charsets.UTF_8)
            d.writeInt(nb.size); d.write(nb)
            d.write(hash.toByteArray(Charsets.US_ASCII))
        }
        return out.toByteArray()
    }

    /** [node-group] The current node's HELLO frame. */
    fun helloFrame(): ByteArray = lock.withLock { handshakeBody(pools[currentPool()].node, 4, 0) ?: ByteArray(0) }

    /** [node-group] A LEAVE to every known peer. */
    fun leaveGroup() {
        lock.withLock {
            val node = pools[currentPool()].node
            for (to in peerProtocols.keys.toList()) {
                val out = java.io.ByteArrayOutputStream()
                val d = java.io.DataOutputStream(out)
                d.writeByte(6); d.writeLong(to); d.writeLong(node)
                routeFrame(node, to, out.toByteArray())
            }
        }
        flushOut()
    }

    /** [protocol-hash] A peer's hash for a protocol, or `null`. */
    fun peerProtocol(node: Long, protocol: String): String? = lock.withLock { peerProtocols[node]?.get(protocol) }

    private fun deliverHandshake(kind: Int, d: java.io.DataInputStream, toRead: Long): Boolean {
        val from = d.readLong()
        val nameBytes = ByteArray(d.readInt()); d.readFully(nameBytes)
        val name = String(nameBytes, Charsets.UTF_8)
        val endpoint = ByteArray(d.readInt()); d.readFully(endpoint)
        val count = d.readInt()
        val table = ArrayList<Pair<String, String>>(count)
        for (i in 0 until count) {
            val nb = ByteArray(d.readInt()); d.readFully(nb)
            val hb = ByteArray(16); d.readFully(hb)
            table.add(Pair(String(nb, Charsets.UTF_8), String(hb, Charsets.US_ASCII)))
        }
        val (sink, hello) =
            lock.withLock {
                val here = pools[currentPool()].node
                val node = if (kind == 4) here else toRead
                val g = groups[node] ?: return false
                if (g.name != name) return false
                routes[from] = endpoint
                peerProtocols[from] = table.toMap()
                if (kind == 4) {
                    handshakeBody(node, 5, from)?.let { routeFrame(node, from, it) }
                }
                val parked = ArrayList(parkedFramesOut)
                parkedFramesOut.clear()
                for ((f, n, fr) in parked) routeFrame(f, n, fr)
                // [actor-group] Everything this node publishes, told to the new peer.
                published[node]?.forEach { (n, p) -> routeFrame(node, from, namedFrame(from, node, n, p.ref)) }
                cv.signalAll()
                Pair(g.sink, g.hello)
            }
        flushOut()
        // Built with the lock released: the builder decodes the endpoint.
        if (sink != null && hello != null) {
            enqueueEvent(sink, hello(from, endpoint, table))
        }
        return true
    }

    /**
     * [addr-routable] [wire-format] Delivers one frame that arrived on the
     * wire. Anything malformed, misaddressed or with mismatched bits is
     * dropped, never delivered wrong [backend-never-wrong]. Answers whether it
     * was delivered.
     */
    fun deliverFrame(frame: ByteArray): Boolean {
        val d = java.io.DataInputStream(java.io.ByteArrayInputStream(frame))
        val delivered: Boolean =
            try {
                val kind = d.readUnsignedByte()
                val toNode = d.readLong()
                if (kind == 4 || kind == 5) {
                    return deliverHandshake(kind, d, toNode)
                }
                if (kind == 6) {
                    val from = d.readLong()
                    val sink =
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            routes.remove(from)
                            peerProtocols.remove(from)
                            // Every proxy of an actor on the departed node is dead
                            // [node-exit]: sends are the silent no-op, watches fire.
                            for ((r, idx) in proxies) {
                                if (r.node == from && !actors[idx].dead) {
                                    actors[idx].dead = true
                                    actors[idx].exitReason = "node left"
                                    val ws = ArrayList(actors[idx].watchers)
                                    actors[idx].watchers.clear()
                                    for ((w, exit) in ws) deliverReply(w, exit("node left"))
                                }
                            }
                            cv.signalAll()
                            groups[toNode]?.let { g -> g.sink?.let { s -> Pair(s, g.gone) } }
                        }
                    if (sink != null && sink.second != null) {
                        enqueueEvent(sink.first, sink.second!!(from))
                    }
                    flushOut()
                    return true
                }
                if (kind == 8) {
                    val from = d.readLong()
                    val nb = ByteArray(d.readInt()); d.readFully(nb)
                    val name = String(nb, Charsets.UTF_8)
                    val r = SalvoRemoteRef(d.readLong(), d.readLong(), d.readLong())
                    val p =
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            peerNames[Pair(from, name)] = r
                            published[toNode]?.get(name)
                        }
                    if (p?.sink != null && p.named != null) enqueueEvent(p.sink, p.named.invoke(from))
                    return true
                }
                if (kind == 9) {
                    val from = d.readLong()
                    val nb = ByteArray(d.readInt()); d.readFully(nb)
                    val name = String(nb, Charsets.UTF_8)
                    val count = d.readInt()
                    val ids = ArrayList<SalvoRemoteRef>(count)
                    for (i in 0 until count) ids.add(SalvoRemoteRef(d.readLong(), d.readLong(), d.readLong()))
                    val p =
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            published[toNode]?.get(name)
                        }
                    // Built with the lock released: the builder imports every identity.
                    if (p?.sink != null && p.members != null) enqueueEvent(p.sink, p.members.invoke(from, ids))
                    return true
                }
                if (kind == 7) {
                    d.readLong() // from
                    val count = d.readInt()
                    val peers = ArrayList<ByteArray>(count)
                    for (i in 0 until count) {
                        val p = ByteArray(d.readInt()); d.readFully(p)
                        peers.add(p)
                    }
                    val sink =
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            groups[toNode]?.let { g -> g.sink?.let { s -> Pair(s, g.intro) } }
                        }
                    if (sink != null && sink.second != null) {
                        enqueueEvent(sink.first, sink.second!!(peers))
                    }
                    return true
                }
                // Two phases around every decode: header checked and decoder
                // found under the lock, payload decoded with it released, the
                // value delivered under the lock again.
                when (kind) {
                    0 -> {
                        val actor = d.readLong(); val bits = d.readLong(); val from = d.readLong()
                        val protoBytes = ByteArray(16); d.readFully(protoBytes)
                        val proto = String(protoBytes, Charsets.US_ASCII)
                        val payload = d.readBytes()
                        val idx = actor.toInt()
                        val decode =
                            lock.withLock {
                                if (!hostedNodes.contains(toNode)) return false
                                if (idx !in actors.indices || actors[idx].remote != null || actors[idx].bits != bits) return false
                                if (actors[idx].dead) return true
                                actors[idx].decode ?: return false
                            }
                        val (ok, msg) = decode(proto, payload)
                        if (!ok) return false
                        lock.withLock {
                            if (actors[idx].dead) return true
                            actors[idx].granted = clamp(actors[idx].granted - 1)
                            actors[idx].queue.addLast(SalvoEntry.User(msg, from))
                            actors[idx].userLen += 1
                            cv.signalAll()
                        }
                        true
                    }
                    1 -> {
                        val tkind = d.readUnsignedByte(); val id = d.readLong(); val slot = d.readLong(); val bits = d.readLong()
                        val payload = d.readBytes()
                        when (tkind) {
                            0 -> lock.withLock {
                                if (!hostedNodes.contains(toNode)) return false
                                val idx = id.toInt()
                                if (idx !in actors.indices || actors[idx].bits != bits || actors[idx].dead) return false
                                actors[idx].queue.addLast(SalvoEntry.ReplyRaw(slot, payload))
                                cv.signalAll()
                                true
                            }
                            1 -> {
                                val wid = id.toInt()
                                val decode =
                                    lock.withLock {
                                        if (!hostedNodes.contains(toNode)) return false
                                        val w = waiters.getOrNull(wid) ?: return false
                                        w.decode ?: return false
                                    }
                                val (ok, value) = decode(payload)
                                if (!ok) return false
                                lock.withLock {
                                    waiters[wid].value = value
                                    waiters[wid].filled = true
                                    cv.signalAll()
                                }
                                true
                            }
                            2 -> {
                                val taken =
                                    lock.withLock {
                                        if (!hostedNodes.contains(toNode)) return false
                                        exportedTasks.remove(id)
                                    } ?: return false
                                val (pool, body, decode) = taken
                                val (ok, value) = decode(payload)
                                if (!ok) return false
                                lock.withLock {
                                    pools[pool].tasks.addLast(Pair(body, value))
                                    cv.signalAll()
                                }
                                true
                            }
                            else -> false
                        }
                    }
                    2 -> {
                        val host = d.readLong(); val actor = d.readLong(); val bits = d.readLong(); val n = d.readInt()
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            val idx = proxies[SalvoRemoteRef(host, actor, bits)] ?: return false
                            actors[idx].credits += n
                            actors[idx].granted = clamp(actors[idx].granted - n)
                            cv.signalAll()
                            true
                        }
                    }
                    3 -> {
                        val actor = d.readLong(); val bits = d.readLong(); val from = d.readLong()
                        val idx = actor.toInt()
                        lock.withLock {
                            if (!hostedNodes.contains(toNode)) return false
                            if (idx !in actors.indices || actors[idx].bits != bits || actors[idx].remote != null) return false
                            val a = actors[idx]
                            val room = maxOf(1, a.bound - a.userLen - a.granted)
                            grantCredit(idx, from, room)
                            cv.signalAll()
                            true
                        }
                    }
                    else -> false
                }
            } catch (e: java.io.IOException) {
                false
            }
        flushOut()
        return delivered
    }

    private fun worker(pool: Int) {
        here.set(SalvoHere(pool, null))
        lock.lock()
        try {
            while (true) {
                // [task-mint] A queued task before an activation: one rule,
                // the same on both backends, so a program's interleaving does
                // not depend on its target. Each queue is served in arrival
                // order.
                if (pools[pool].tasks.isNotEmpty()) {
                    runTask(pool)
                    continue
                }
                val job = pick(pool, null)
                if (job == null) {
                    // [actor-on-idle] A worker with nothing to do is the other
                    // place quiescence is observed: a hook registered from an
                    // actor is fired by whichever thread next runs dry, without
                    // anybody having to wait for it.
                    if (!fireIdle()) {
                        cv.await()
                    }
                } else {
                    runJob(job.first, job.second)
                }
            }
        } finally {
            lock.unlock()
        }
    }
}

internal sealed class SalvoTarget

internal class SalvoTargetProc(val addr: Int) : SalvoTarget()

internal class SalvoTargetWaiter(val wid: Int) : SalvoTarget()

/**
 * [task-mint] A detached one-shot: the pool it runs on, the closure (taken out
 * when it runs, or when the token crosses the wire), and how its answer is
 * decoded should it come back over the wire.
 */
internal class SalvoTargetTask(
    val pool: Int,
    var body: ((Any?) -> Unit)?,
    val decode: (ByteArray) -> Pair<Boolean, Any?>,
) : SalvoTarget()

/** [addr-routable] A token minted on another node and decoded here. */
internal class SalvoTargetRemote(val node: Long, val kind: Int, val id: Long, val bits: Long) : SalvoTarget()

/**
 * A one-shot reply capability. `send` delivers exactly once — the
 * guarantee is the checker's; the runtime only enqueues.
 */
class SalvoReply internal constructor(internal val target: SalvoTarget, internal val slot: Long) {
    /**
     * [actor-on-idle] Whether this token still counts as an obligation the
     * program owes. A mint counts it; a delivery, or a handover to the
     * scheduler itself ([SalvoSched.watch], [SalvoSched.onIdle]), stops
     * counting it — what an `Idle` payload reports is work *user code* has not
     * answered, not registrations the scheduler will answer on its own.
     */
    internal var tracked: Boolean = true

    fun send(value: Any?) = SalvoSched.sendReply(this, value)
}

/**
 * [addr-capability] A fresh 64-bit value for an identity that must be
 * unguessable to an outsider: `SecureRandom`, seeded by the platform.
 */
private val salvoRandom = java.security.SecureRandom()

internal fun randomLong(): Long = salvoRandom.nextLong()
